<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/cvp-evidence-validate.ts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --max-age-days</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span>
